 33	/// Represents a template that is utilized to generate command strings.
 34	///
 35	/// The template is meant to be coupled with an input in order to generate a command. The
 36	/// `generate_and_execute()` method will be used to generate a command and execute it.
 37	#[derive(Debug, Clone, PartialEq)]
 38	pub struct CommandTemplate {
