 53	    pub fn new_batch<I, S>(input: I, path_separator: Option<String>) -> Result<CommandTemplate>
 54	    where
 55	        I: IntoIterator<Item = S>,
 56	        S: AsRef<str>,
 57	    {
 58	        let cmd = Self::build(input, ExecutionMode::Batch, path_separator);
 59	        if cmd.number_of_tokens() > 1 {
 60	            return Err(anyhow!("Only one placeholder allowed for batch commands"));
 61	        }
 62	        if cmd.args[0].has_tokens() {
 63	            return Err(anyhow!(
 64	                "First argument of exec-batch is expected to be a fixed executable"
 65	            ));
 66	        }
 67	        Ok(cmd)
 68	    }
