/// Returns the maximum combined size (in bytes) of the arguments that should be passed to a
/// single invocation of a batch command, leaving some room for the environment and other
/// overhead so that the OS's `ARG_MAX` limit (see `getconf ARG_MAX`) is not exceeded.
fn batch_size_limit() -> usize {
    #[cfg(all(unix, not(target_os = "redox")))]
    {
        let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
        let arg_max = if arg_max > 0 { arg_max as usize } else { 128 * 1024 };
        let env_size: usize = std::env::vars_os()
            .map(|(key, value)| key.len() + value.len() + 2)
            .sum();
        arg_max.saturating_sub(env_size).saturating_sub(4096).max(4096)
    }
    #[cfg(not(all(unix, not(target_os = "redox"))))]
    {
        // Conservative default for platforms without a way to query the limit (e.g. Windows'
        // command line length limit is around 32767 characters).
        16 * 1024
    }
}

/// Splits a slice into chunks so that the total "size" (as computed by `size_of`) of each chunk
/// does not exceed `limit`. A single oversized element is still placed alone in its own chunk.
trait ChunksBySize<T> {
    fn chunks_by_size<F>(&self, limit: usize, size_of: F) -> ChunkBySizeIter<'_, T, F>
    where
        F: FnMut(&T) -> usize;
}

impl<T> ChunksBySize<T> for [T] {
    fn chunks_by_size<F>(&self, limit: usize, size_of: F) -> ChunkBySizeIter<'_, T, F>
    where
        F: FnMut(&T) -> usize,
    {
        ChunkBySizeIter {
            items: self,
            limit,
            size_of,
        }
    }
}

struct ChunkBySizeIter<'a, T, F> {
    items: &'a [T],
    limit: usize,
    size_of: F,
}

impl<'a, T, F> Iterator for ChunkBySizeIter<'a, T, F>
where
    F: FnMut(&T) -> usize,
{
    type Item = &'a [T];

    fn next(&mut self) -> Option<Self::Item> {
        if self.items.is_empty() {
            return None;
        }

        let mut total = 0;
        let mut end = 0;

        for item in self.items {
            let size = (self.size_of)(item);
            if end > 0 && total + size > self.limit {
                break;
            }
            total += size;
            end += 1;
        }

        let (chunk, rest) = self.items.split_at(end);
        self.items = rest;
        Some(chunk)
    }
}

